+	if fd.Verdict == "below_minimum" && fd.FixNecessity == "" {
+		add("verdict が below_minimum なのに fix_necessity がありません (下限未満にできるのは、必要度を決めた指摘だけ)")
+	}
+	verified := fd.PremiseCheck.Result == "verified"
+	r := fd.FixNecessityReason
